import xarray as xr
import json

def compute_and_save_statistics():
    print("Loading engineered dataset...")
    # Assuming ds_engineered is generated by your previous scripts
    ds = xr.open_mfdataset("./data/processed/engineered_*.nc", chunks={'valid_time': 'auto'})
    
    # 1. Isolate the Training Temporal Window
    ds_train = ds.sel(valid_time=slice("1996-01-01", "2019-12-31"))
    
    # 2. Define Exclusion Sets
    excluded_vars = [
        'lsm', 'slt',               # Static/Categorical
        'hour_sin', 'hour_cos',     # Cyclical
        'day_sin', 'day_cos'        # Cyclical
    ]
    
    continuous_vars = [v for v in ds_train.data_vars if v not in excluded_vars]
    ds_continuous = ds_train[continuous_vars]
    
    # 3. Define the Mathematical Reduction
    # We compute the scalar mean and std across time and space for each channel
    print("Building computational graph for global mu and sigma...")
    mu = ds_continuous.mean(dim=['valid_time', 'latitude', 'longitude'])
    sigma = ds_continuous.std(dim=['valid_time', 'latitude', 'longitude'])
    
    # 4. Trigger Dask Execution (The RAM Peak)
    print("Executing Dask reduction. This will take time...")
    mu_computed = mu.compute()
    sigma_computed = sigma.compute()
    
    # 5. Serialize to JSON for downstream loading
    stats = {
        "mean": {var: float(mu_computed[var].values) for var in continuous_vars},
        "std": {var: float(sigma_computed[var].values) for var in continuous_vars}
    }
    
    with open("./data/processed/global_stats.json", "w") as f:
        json.dump(stats, f, indent=4)
    print("Statistics saved to global_stats.json")

if __name__ == "__main__":
    compute_and_save_statistics()